package cl.robermotos.delivery.service;
import cl.robermotos.delivery.adapter.*; import cl.robermotos.delivery.dto.*; import cl.robermotos.config.DeliveryProperties; import org.springframework.stereotype.Service; import java.util.*; import java.util.concurrent.*;
@Service public class DeliveryOrchestratorService { private final List<DeliveryProviderAdapter> adapters; private final DeliveryProperties props; private final ExecutorService pool=Executors.newFixedThreadPool(3); private final Map<String,DeliveryQuoteDTO> quotes=new ConcurrentHashMap<>(); private final Map<String,Long> quoteTimes=new ConcurrentHashMap<>(); public DeliveryOrchestratorService(List<DeliveryProviderAdapter> a,DeliveryProperties p){adapters=a;props=p;} public List<DeliveryQuoteDTO> quotes(DeliveryRequest req){List<CompletableFuture<DeliveryQuoteDTO>> fs=adapters.stream().map(a->CompletableFuture.supplyAsync(()->a.quote(req),pool).completeOnTimeout(null,props.quoteTimeoutMs,TimeUnit.MILLISECONDS).exceptionally(e->null)).toList(); List<DeliveryQuoteDTO> out=fs.stream().map(CompletableFuture::join).filter(Objects::nonNull).toList(); out.forEach(q->{quotes.put(q.quoteId(),q);quoteTimes.put(q.quoteId(),System.currentTimeMillis());}); return out.stream().sorted(Comparator.comparingLong(DeliveryQuoteDTO::priceClp)).toList();} public DispatchResult dispatch(String orderId,String provider,String quoteId,DeliveryRequest req){DeliveryProviderAdapter selected=find(provider); DeliveryQuoteDTO q=quotes.get(quoteId); if(q==null || !q.provider().equals(provider) || System.currentTimeMillis()-quoteTimes.getOrDefault(quoteId,0L)>props.quoteTtlSeconds*1000){q=selected.quote(req);quotes.put(q.quoteId(),q);quoteTimes.put(q.quoteId(),System.currentTimeMillis());quoteId=q.quoteId();} if(props.simulateNoRiders){System.err.println("ALERTA: "+provider+" sin repartidores. Activando failover."); return adapters.stream().filter(a->!a.provider().equals(provider)).map(a->Map.entry(a,a.quote(req))).sorted(Comparator.comparingLong(e->e.getValue().priceClp())).map(e->{System.err.println("FAILOVER: reasignando a "+e.getKey().displayName());return e.getKey().dispatch(orderId,req,e.getValue().quoteId());}).findFirst().orElseThrow();} return selected.dispatch(orderId,req,q.quoteId());} private DeliveryProviderAdapter find(String n){return adapters.stream().filter(a->a.provider().equalsIgnoreCase(n)).findFirst().orElseThrow(()->new IllegalArgumentException("Proveedor desconocido: "+n));} }